package com.lolfm.simulator;
import com.lolfm.domain.*;import java.nio.file.*;import java.util.*;
public final class ProgressionBaselineAudit{
 enum Mode{LEGACY_OFF,STATE_ONLY,POWER_ON}static final int[] TIMES={300,600,900,1200,1500,1800,2400};
 public static void main(String[]z)throws Exception{StringBuilder log=new StringBuilder("PROGRESSION_BASELINE_AUDIT constantsChanged=false gameplayChanged=false\n"),summary=new StringBuilder("scenario,mode,seeds,blueWins,redWins,winRate,avg,median,p90,p95,over40,over60,timeout,nexusRate\n"),combat=new StringBuilder("scenario,context,count,bluePower,redPower,signedEdge,absEdge,signedContribution,absContribution,p50,p90,p95,max,positive,negative,zero,clamp,participants,shareAvg,shareP50,shareP90,shareP95,shareMax,shareOverOneRate,levelContribution,itemContribution,itemRatio,levelRatio,goldContribution,sameDirection,oppositeDirection,bothNonzero,goldOnly,itemOnly,both,correlation\n"),position=new StringBuilder("scenario,time,side,position,n,avgLevel,p10,p50,p90,avgXp,avgGold,starting,component,first,second,third,fourth,full,levelPower,itemPower,totalPower\n");for(Scenario s:scenarios()){Audit a=new Audit(s);a.run();a.print(log,summary,combat,position);}focused(log);Files.writeString(Path.of("progression-baseline-audit.log"),log);Files.writeString(Path.of("progression-baseline-summary.csv"),summary);Files.writeString(Path.of("progression-combat-contribution.csv"),combat);Files.writeString(Path.of("progression-position-timings.csv"),position);System.out.print(log);}
 static final class Audit{final Scenario s;final EnumMap<Mode,Outcome>out=new EnumMap<>(Mode.class);final EnumMap<ProgressionCombatContext,Ctx>ctx=new EnumMap<>(ProgressionCombatContext.class);final Map<String,Growth>growth=new TreeMap<>();final Map<String,Reach>reach=new TreeMap<>();final EnumMap<Mode,Finals>fin=new EnumMap<>(Mode.class);long winnerChange;double durationDelta;long faster,slower,supHigher,same,adcHigher,sup1,sup2,adc1,shared,adcSolo,supSolo,absent,activity,recovery,dead,gankEval,gankAttempt,counter;final EnumMap<TeamSide,Long>jgEco=new EnumMap<>(TeamSide.class),jgKill=new EnumMap<>(TeamSide.class),jgAssist=new EnumMap<>(TeamSide.class);
  Audit(Scenario s){this.s=s;for(Mode m:Mode.values()){out.put(m,new Outcome());fin.put(m,new Finals());}for(var c:ProgressionCombatContext.values())ctx.put(c,new Ctx());for(var x:TeamSide.values()){jgEco.put(x,0L);jgKill.put(x,0L);jgAssist.put(x,0L);}}
  void run(){int n=s.mirror?500:1000;for(int seed=1;seed<=n;seed++){EnumMap<Mode,MatchSimulator.SimulationResult>r=new EnumMap<>(Mode.class);for(Mode m:Mode.values()){var x=sim(m).simulateWithDiagnostics(s.team(TeamSide.BLUE),s.team(TeamSide.RED),seed);r.put(m,x);out.get(m).add(x);fin.get(m).add(x);if(m==Mode.POWER_ON)add(x);}MatchSimulator.SimulationResult a=r.get(Mode.STATE_ONLY),b=r.get(Mode.POWER_ON);if(a.winnerSide()!=b.winnerSide())winnerChange++;double d=b.timeline().getDurationSeconds()-a.timeline().getDurationSeconds();durationDelta+=d;if(d<0)faster++;else if(d>0)slower++;}}
  void add(MatchSimulator.SimulationResult r){var st=r.progressionExecutionStats();for(var x:st.combatSamples())if(x.applicationStage()!=ProgressionApplicationStage.FIGHT_GRADE)ctx.get(x.context()).add(x);shared+=st.botSharedTicks();adcSolo+=st.botAdcSoloTicks();supSolo+=st.botSupportSoloTicks();absent+=st.botBothAbsentTicks();activity+=st.activityEconomyXpBlocked();recovery+=st.farmRecoveryXpBlocked();dead+=st.deadEconomyXpBlocked();if(s.key.equals("A")||s.key.equals("G")){for(MatchSnapshot q:r.timeline().getSnapshots()){boolean cp=Arrays.stream(TIMES).anyMatch(t->t==q.getTimeSeconds())||q==r.timeline().getSnapshots().getLast();if(cp){String time=q==r.timeline().getSnapshots().getLast()?"END":Integer.toString(q.getTimeSeconds());for(PlayerSnapshot p:q.getPlayerSnapshots())growth.computeIfAbsent(time+","+p.getTeamSide()+","+p.getPosition(),k->new Growth()).add(p);}}for(MatchEvent e:r.timeline().getEvents()){var d=e.getProgressionEvent();if(d==null)continue;if(d.type()==ProgressionEventType.LEVEL_UP&&(d.newLevel()==6||d.newLevel()==11||d.newLevel()==16||d.newLevel()==18))reach.computeIfAbsent(d.side()+","+d.position()+",L"+d.newLevel(),k->new Reach()).add(d.timeSeconds());if(d.type()==ProgressionEventType.ITEM_STAGE_REACHED)reach.computeIfAbsent(d.side()+","+d.position()+","+d.newItemStage(),k->new Reach()).add(d.timeSeconds());}MatchSnapshot end=r.timeline().getSnapshots().getLast();for(TeamSide side:TeamSide.values()){int a=player(end,side,Position.ADC).getLevel(),u=player(end,side,Position.SUPPORT).getLevel();if(u>a)supHigher++;else if(u==a)same++;else adcHigher++;if(u-a>=1)sup1++;if(u-a>=2)sup2++;if(a-u>=1)adc1++;}}
   if(s.key.equals("E")){gankEval+=r.combatExecutionStats().jungleGankEvaluations();gankAttempt+=r.combatExecutionStats().jungleGankAttempts();counter+=r.combatExecutionStats().counterGankAttempts();for(TeamSide side:TeamSide.values()){Map<ExperienceSource,Integer>x=st.experienceByPlayer().getOrDefault(new PlayerKey(side,Position.JUNGLE),Map.of());jgEco.merge(side,(long)x.getOrDefault(ExperienceSource.JUNGLE_ECONOMY,0),Long::sum);jgKill.merge(side,(long)x.getOrDefault(ExperienceSource.KILL,0),Long::sum);jgAssist.merge(side,(long)x.getOrDefault(ExperienceSource.ASSIST,0),Long::sum);}}}
  void print(StringBuilder log,StringBuilder summary,StringBuilder combat,StringBuilder position){int n=s.mirror?500:1000;for(Mode m:Mode.values()){Outcome o=out.get(m);summary.append(s.label()).append(',').append(m).append(',').append(n).append(',').append(o.b).append(',').append(o.r).append(',').append(f(o.b/(double)n)).append(',').append(f(o.avg())).append(',').append(o.p(.5)).append(',').append(o.p(.9)).append(',').append(o.p(.95)).append(',').append(o.o40).append(',').append(o.o60).append(',').append(o.timeout).append(',').append(f(o.nexus/(double)n)).append('\n');}Outcome a=out.get(Mode.STATE_ONLY),b=out.get(Mode.POWER_ON);log.append(String.format(Locale.ROOT,"SUMMARY %s stateWin=%.3f powerWin=%.3f delta=%+.3f stateAvg=%.1f powerAvg=%.1f delta=%+.1f pairedWinnerChange=%d pairedDuration=%+.2f faster/slower=%d/%d%n",s.label(),a.b/(double)n,b.b/(double)n,(b.b-a.b)/(double)n,a.avg(),b.avg(),b.avg()-a.avg(),winnerChange,durationDelta/n,faster,slower));for(var e:ctx.entrySet())e.getValue().print(combat,s.label(),e.getKey());if(s.key.equals("A")||s.key.equals("G")){for(var e:growth.entrySet())e.getValue().print(position,s.label()+","+e.getKey());long total=supHigher+same+adcHigher;log.append(String.format(Locale.ROOT,"BOT %s supportHigher=%.3f same=%.3f adcHigher=%.3f supportPlus1=%.3f supportPlus2=%.3f adcPlus1=%.3f shared=%d adcSolo=%d supportSolo=%d absent=%d activityBlock=%d recoveryBlock=%d deadBlock=%d supportCsError=0%n",s.label(),ratio(supHigher,total),ratio(same,total),ratio(adcHigher,total),ratio(sup1,total),ratio(sup2,total),ratio(adc1,total),shared,adcSolo,supSolo,absent,activity,recovery,dead));for(var e:reach.entrySet())log.append("REACH ").append(s.label()).append(' ').append(e.getKey()).append(' ').append(e.getValue().text(n)).append('\n');}if(s.key.equals("E"))log.append(String.format(Locale.ROOT,"JUNGLE_E %s eval=%d attempt=%d counter=%d economyXp=%d/%d killXp=%d/%d assistXp=%d/%d activityBlock=%d recoveryBlock=%d%n",s.label(),gankEval,gankAttempt,counter,jgEco.get(TeamSide.BLUE),jgEco.get(TeamSide.RED),jgKill.get(TeamSide.BLUE),jgKill.get(TeamSide.RED),jgAssist.get(TeamSide.BLUE),jgAssist.get(TeamSide.RED),activity,recovery));if(s.key.equals("F")){log.append("F_STATE ").append(fin.get(Mode.STATE_ONLY).text(n)).append('\n');log.append("F_POWER ").append(fin.get(Mode.POWER_ON).text(n)).append('\n');}}
 }
 static final class Outcome{long b,r,o40,o60,timeout,nexus;final List<Integer>d=new ArrayList<>();void add(MatchSimulator.SimulationResult x){if(x.winnerSide()==TeamSide.BLUE)b++;else r++;int t=x.timeline().getDurationSeconds();d.add(t);if(t>=2400)o40++;if(t>=3600)o60++;if(x.endReason()==GameEndReason.SIMULATION_TIMEOUT)timeout++;if(x.endReason()==GameEndReason.NEXUS_DESTROYED)nexus++;}double avg(){return d.stream().mapToInt(x->x).average().orElse(0);}int p(double q){return pi(d,q);}}
 static final class Ctx{long n,pos,neg,zero,clamp,same,opp,bothNon,goldOnly,itemOnly,both,shareOver;double bp,rp,edge,abs,con,absCon,participants,level,item,gold;final List<Double>vals=new ArrayList<>(),shares=new ArrayList<>(),gv=new ArrayList<>(),iv=new ArrayList<>();void add(ProgressionCombatSample s){n++;boolean blue=s.ownSide()==TeamSide.BLUE;bp+=blue?s.ownAveragePower():s.enemyAveragePower();rp+=blue?s.enemyAveragePower():s.ownAveragePower();double e=blue?s.progressionEdge():-s.progressionEdge(),v=blue?s.totalContribution():-s.totalContribution(),l=blue?s.levelContribution():-s.levelContribution(),i=blue?s.itemContribution():-s.itemContribution(),g=Double.isFinite(s.goldContribution())?(blue?s.goldContribution():-s.goldContribution()):0;edge+=e;abs+=Math.abs(e);con+=v;absCon+=Math.abs(v);vals.add(Math.abs(v));participants+=s.ownParticipantCount()+s.enemyParticipantCount();level+=l;item+=i;gold+=g;gv.add(g);iv.add(i);double ex=Double.isFinite(s.existingScoreBeforeProgression())?Math.abs(s.existingScoreBeforeProgression()):0;double share=Math.abs(v)/Math.max(ex,0.01);shares.add(share);if(share>1)shareOver++;if(v>1e-9)pos++;else if(v< -1e-9)neg++;else zero++;clamp+=s.clampedParticipantCount();boolean gz=Math.abs(g)>1e-9,iz=Math.abs(i)>1e-9;if(gz&&iz){both++;bothNon++;if(Math.signum(g)==Math.signum(i))same++;else opp++;}else if(gz)goldOnly++;else if(iz)itemOnly++;}
  void print(StringBuilder o,String sc,ProgressionCombatContext c){if(n==0)return;double la=Math.abs(level/n),ia=Math.abs(item/n),den=la+ia;o.append(String.join(",",sc,c.name(),Long.toString(n),f(bp/n),f(rp/n),f(edge/n),f(abs/n),f(con/n),f(absCon/n),f(pd(vals,.5)),f(pd(vals,.9)),f(pd(vals,.95)),f(Collections.max(vals)),f(pos/(double)n),f(neg/(double)n),f(zero/(double)n),Long.toString(clamp),f(participants/n),f(avg(shares)),f(pd(shares,.5)),f(pd(shares,.9)),f(pd(shares,.95)),f(Collections.max(shares)),f(shareOver/(double)n),f(level/n),f(item/n),f(den==0?0:ia/den),f(den==0?0:la/den),f(gold/n),f(ratio(same,bothNon)),f(ratio(opp,bothNon)),f(bothNon/(double)n),Long.toString(goldOnly),Long.toString(itemOnly),Long.toString(both),f(corr(gv,iv)))).append('\n');}}
 static final class Growth{long n;double l,x,g,lp,ip,tp;final List<Integer>levels=new ArrayList<>();final long[]stage=new long[7];void add(PlayerSnapshot p){n++;l+=p.getLevel();levels.add(p.getLevel());x+=p.getTotalExperience();g+=p.getProgressionEarnedGold();stage[p.getItemStage().ordinal()]++;lp+=p.getProgressionPower().levelPower();ip+=p.getProgressionPower().itemPower();tp+=p.getProgressionPower().totalPower();}void print(StringBuilder o,String pre){o.append(pre).append(',').append(n).append(',').append(f(l/n)).append(',').append(pi(levels,.1)).append(',').append(pi(levels,.5)).append(',').append(pi(levels,.9)).append(',').append(f(x/n)).append(',').append(f(g/n));for(long z:stage)o.append(',').append(z);o.append(',').append(f(lp/n)).append(',').append(f(ip/n)).append(',').append(f(tp/n)).append('\n');}}
 static final class Reach{long n,sum;void add(int t){n++;sum+=t;}String text(int d){return String.format(Locale.ROOT,"reached=%d unreached=%d avg=%.1f",n,d-n,n==0?0:sum/(double)n);}}
 static final class Finals{long bk,rk;double bg,rg,bpg,rpg,bl,rl,bp,rp;void add(MatchSimulator.SimulationResult r){MatchSnapshot s=r.timeline().getSnapshots().getLast();bk+=s.getBlueKills();rk+=s.getRedKills();bg+=s.getBlueGold();rg+=s.getRedGold();for(PlayerSnapshot p:s.getPlayerSnapshots()){if(p.getTeamSide()==TeamSide.BLUE){bpg+=p.getProgressionEarnedGold();bl+=p.getLevel();bp+=p.getProgressionPower().totalPower();}else{rpg+=p.getProgressionEarnedGold();rl+=p.getLevel();rp+=p.getProgressionPower().totalPower();}}}String text(int n){return String.format(Locale.ROOT,"kills=%.2f/%.2f gold=%.1f/%.1f progressionGold=%.1f/%.1f level=%.2f/%.2f power=%.3f/%.3f",bk/(double)n,rk/(double)n,bg/n,rg/n,bpg/n,rpg/n,bl/(n*5.0),rl/(n*5.0),bp/(n*5.0),rp/(n*5.0));}}
 static void focused(StringBuilder l){GameState s=LateGameTestSupport.state();PlayerState a=s.getBlueTeamState().playerAt(Position.TOP),b=s.getBlueTeamState().playerAt(Position.MID);a.getProgressionState().awardExperience(ExperienceSource.KILL,2400,1);b.getProgressionState().awardExperience(ExperienceSource.KILL,2400,1);a.getProgressionState().awardEarnedGold(3500,GoldSource.KILL,1);b.getProgressionState().awardEarnedGold(3500,GoldSource.KILL,1);double equal=new CombatProgressionEvaluator().contribution(s,ProgressionCombatContext.TEAMFIGHT,List.of(a),List.of(b),10,2);b.getProgressionState().awardExperience(ExperienceSource.KILL,780,2);double level=new CombatProgressionEvaluator().contribution(s,ProgressionCombatContext.TEAMFIGHT,List.of(b),List.of(a),10,2);a.getProgressionState().awardEarnedGold(3500,GoldSource.FARM,3);double item=new CombatProgressionEvaluator().contribution(s,ProgressionCombatContext.TEAMFIGHT,List.of(a),List.of(b),10,2);s.configureProgression(true,false);double off=new CombatProgressionEvaluator().contribution(s,ProgressionCombatContext.TEAMFIGHT,List.of(a),List.of(b),10,2);l.append(String.format(Locale.ROOT,"FOCUSED equal=%.6f levelOnly=%.6f itemOnly=%.6f powerOff=%.6f position=1 champion=1 spike=0 levelSpike=0%n",equal,level,item,off));}
 static MatchSimulator sim(Mode m){SimulationOptions o=SimulationOptions.productionDefaults().withDiagnosticsEnabled(true);if(m==Mode.LEGACY_OFF)o=o.withProgressionEnabled(false);else if(m==Mode.STATE_ONLY)o=o.withProgressionPowerEnabled(false);return new MatchSimulator(new TeamfightResolver(),new EndGameEvaluator(),new SnapshotFactory(),new ObjectiveResolver(),new PostFightResolver(),new ObjectiveAttemptResolver(),new StructureResolver(),new PushResolver(),o);}static PlayerSnapshot player(MatchSnapshot s,TeamSide t,Position p){return s.getPlayerSnapshots().stream().filter(x->x.getTeamSide()==t&&x.getPosition()==p).findFirst().orElseThrow();}
 static List<Scenario>scenarios(){Profile e=Profile.all(14,14,14,14);return List.of(new Scenario("A",e,e,false),new Scenario("B",Profile.all(14,14,18,14),Profile.all(14,14,10,14),false),new Scenario("B",Profile.all(14,14,10,14),Profile.all(14,14,18,14),true),new Scenario("C",Profile.farm(Position.MID,20),Profile.farm(Position.MID,8),false),new Scenario("C",Profile.farm(Position.MID,8),Profile.farm(Position.MID,20),true),new Scenario("D",Profile.farm(Position.ADC,20),Profile.farm(Position.ADC,8),false),new Scenario("D",Profile.farm(Position.ADC,8),Profile.farm(Position.ADC,20),true),new Scenario("E",Profile.agg(Position.JUNGLE,20),Profile.agg(Position.JUNGLE,8),false),new Scenario("E",Profile.agg(Position.JUNGLE,8),Profile.agg(Position.JUNGLE,20),true),new Scenario("F",Profile.all(18,18,14,18),Profile.all(10,10,14,10),false),new Scenario("F",Profile.all(10,10,14,10),Profile.all(18,18,14,18),true),new Scenario("G",e,e,false));}record Scenario(String key,Profile blue,Profile red,boolean mirror){String label(){return key+(mirror?"_MIRROR":"");}Team team(TeamSide s){Profile p=s==TeamSide.BLUE?blue:red;String n=s+"-"+label();List<Player>x=new ArrayList<>();for(Position z:Position.values()){int[]v=p.v.get(z);x.add(new Player(n+"-"+z,z,new PlayerAttributes(v[0],v[1],v[2],v[3])));}return new Team(n,x);}}static final class Profile{final EnumMap<Position,int[]>v=new EnumMap<>(Position.class);static Profile all(int m,int a,int f,int t){Profile p=new Profile();for(Position z:Position.values())p.v.put(z,new int[]{m,a,f,t});return p;}static Profile farm(Position z,int f){Profile p=all(14,14,14,14);p.v.put(z,new int[]{14,14,f,14});return p;}static Profile agg(Position z,int a){Profile p=all(14,14,14,14);p.v.put(z,new int[]{14,a,14,14});return p;}}
 static String f(double x){return String.format(Locale.ROOT,"%.6f",x);}static int pi(List<Integer>x,double q){if(x.isEmpty())return 0;List<Integer>c=new ArrayList<>(x);Collections.sort(c);return c.get((int)Math.min(c.size()-1,Math.ceil(q*c.size())-1));}static double pd(List<Double>x,double q){if(x.isEmpty())return 0;List<Double>c=new ArrayList<>(x);Collections.sort(c);return c.get((int)Math.min(c.size()-1,Math.ceil(q*c.size())-1));}static double avg(List<Double>x){return x.stream().mapToDouble(v->v).average().orElse(0);}static double ratio(long a,long b){return b==0?0:a/(double)b;}static double corr(List<Double>a,List<Double>b){if(a.size()<2)return 0;double x=avg(a),y=avg(b),n=0,da=0,db=0;for(int i=0;i<a.size();i++){double u=a.get(i)-x,v=b.get(i)-y;n+=u*v;da+=u*u;db+=v*v;}return da==0||db==0?0:n/Math.sqrt(da*db);}
}
